function reformatPath(p) {
  return p.toString().split(" ").map( x => x.match(/[.-0123456789]+/) ? Math.round(x * 2048 / 1000) : x).join(" ");
}

function PT32SVG (fontid, fontweight = 400, fontstyle = "normal", weight = 85, slanted = 0) {
const shortfontid = fontid.replaceAll(" ","");
const header = `<?xml version="1.0" standalone="no"?>
<!DOCTYPE svg PUBLIC "-//W3C//DTD SVG 1.1//EN" "http://www.w3.org/Graphics/SVG/1.1/DTD/svg11.dtd" >`;
const svg = document.createElement("SVG");
svg.setAttribute("abc","http://www.w3.org/2000/svg");
svg.setAttribute("xmlns:xlink","http://www.w3.org/1999/xlink");
svg.setAttribute("version","1.1");
const metadata = document.createElement("METADATA");
svg.appendChild(metadata);
metadata.innerHTML = "Created by SQL Notebook";
const defs = document.createElement("DEFS");
svg.appendChild(defs);
const font = document.createElement("FONT");
defs.appendChild(font);
font.setAttribute("id",shortfontid);
font.setAttribute("horiz-adv-x","0");
const fontFace = document.createElement("FONT-FACE");
font.appendChild(fontFace);
fontFace.setAttribute("font-family",fontid);
fontFace.setAttribute("font-weight",fontweight);
fontFace.setAttribute("font-style",fontstyle);
fontFace.setAttribute("font-stretch","normal");
fontFace.setAttribute("units-per-em","2048");
fontFace.setAttribute("panose","2 0 5 3 5 0 0 2 3 4");
fontFace.setAttribute("ascent","1434");
fontFace.setAttribute("descent","-410");
fontFace.setAttribute("x-height","1024");
fontFace.setAttribute("cap-height","1434");
fontFace.setAttribute("bbox","0 -410 1638 2253");
fontFace.setAttribute("underline-thickness","174");
fontFace.setAttribute("underline-position","-205");
fontFace.setAttribute("slope","0");
fontFace.setAttribute("unicode-range","U+000D-FFFD");
const missingGlyph = document.createElement("MISSING-GLYPH");
font.appendChild(missingGlyph)
missingGlyph.setAttribute("horiz-adv-x","1024");
const mggpath = document.createElement("PATH");
missingGlyph.appendChild(mggpath);
mggpath.setAttribute("d","M32 0v780h408v-780h-408zM92 60h288v660h-288v-660z")
let glyphcontext = rpn(` kugifont /${shortfontid} 10 selectfont  `);
for(var i=32; i < 256; i++) { if (i == 127) continue;
   let code = `
 currentfontdict begin 
 /fill {} def
 /charname Encoding ${i} get def
/characterweight ${weight} def
 /currentslanted ${slanted} def 
 0 -440 translate
 /characterwidth Metrics charname get def charname 
 CharacterDefs charname get exec Metrics charname get charname 0 440 translate end `;
   glyphcontext = rpn(code, glyphcontext);
   const dev = new rpnSVGDevice();
   let d = reformatPath(dev.getPath(glyphcontext.graphics.path));
   glyphcontext.graphics.path = [];
   let glyph = document.createElement("GLYPH");
   font.appendChild(glyph);
   let charname = glyphcontext.stack.pop().value
   glyph.setAttribute("glyph-name",charname );
   glyph.setAttribute("unicode-name",charname);
   glyph.setAttribute("horiz-adv-x", reformatPath (glyphcontext.stack.pop().value));
   let path = document.createElement("PATH");
   glyph.appendChild(path);
   path.setAttribute("d",d);
}

let kernCharacers = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
let kerncontext = rpn(` kugifont /${shortfontid} 10 selectfont `);
for (let i = 0; i < kernCharacers.length; i++) {
let chi = rpnMacRomanChar(kernCharacers,i);
for (let j = 0; j < kernCharacers.length; j++) {

   let chj = rpnMacRomanChar(kernCharacers,j);
   kerncontext = rpn(` ${chi} ${chj} kernvalue `, kerncontext);
   let k = kerncontext.stack.pop().value;
   if (k > 50) {
   let hkern = document.createElement("HKERN");
   font.appendChild(hkern);
   hkern.setAttribute("u1",kernCharacers.substr(i,1));
   hkern.setAttribute("u2",kernCharacers.substr(j,1));
   hkern.setAttribute("k", reformatPath(k));
   }

}
}

let stream = header+ svg.outerHTML
let url = "data:image/svg+xml;base64," + rpnBbtoaUnicode(stream);

echo (`<a download="${shortfontid}" href="${url}"> SVG Font ${shortfontid}</a><br>`);

echo(svg.outerHTML.length);
}
PT32SVG("Kugi Regular", 500, "normal", 85, 0);
